// @vitest-environment happy-dom
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
  DIR_CLIENT_TO_SERVER,
  DIR_SERVER_TO_CLIENT,
  SecureChannel,
  b64ToBytes,
  bytesToB64,
  bytesToHex,
  createClientHello,
  deriveKeys,
  helloMessage,
  hexToBytes,
  openRecord,
  parseServerHello,
  sealRecord,
} from "./wifi-crypto";

// Shared with the Kotlin tests; generated by scripts/gen-wifi-vectors.mjs with node:crypto.
const vectors = JSON.parse(
  readFileSync(resolve(__dirname, "../../../../docs/wifi-crypto-vectors.json"), "utf8"),
) as {
  token: string;
  clientPrivateKey: string;
  clientPublicKey: string;
  serverPublicKey: string;
  clientNonce: string;
  serverNonce: string;
  sharedSecret: string;
  keyClientToServer: string;
  keyServerToClient: string;
  records: { direction: string; counter: number; plaintext: string; record: string }[];
};

function b64url(bytes: Uint8Array) {
  return bytesToB64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** WebCrypto cannot import a raw private scalar, so build a JWK from the vector's key pair. */
async function importVectorPrivateKey() {
  const pub = hexToBytes(vectors.clientPublicKey);
  return crypto.subtle.importKey(
    "jwk",
    {
      kty: "EC",
      crv: "P-256",
      d: b64url(hexToBytes(vectors.clientPrivateKey)),
      x: b64url(pub.slice(1, 33)),
      y: b64url(pub.slice(33, 65)),
    },
    { name: "ECDH", namedCurve: "P-256" },
    false,
    ["deriveBits"],
  );
}

async function vectorKeys() {
  return deriveKeys(
    await importVectorPrivateKey(),
    hexToBytes(vectors.clientPublicKey),
    hexToBytes(vectors.clientNonce),
    hexToBytes(vectors.serverPublicKey),
    hexToBytes(vectors.serverNonce),
    vectors.token,
  );
}

describe("wifi-crypto known-answer vectors", () => {
  it("derives the same shared secret and keys as the reference", async () => {
    const keys = await vectorKeys();
    expect(bytesToHex(keys.sharedSecret)).toBe(vectors.sharedSecret);
    expect(bytesToHex(keys.clientToServer)).toBe(vectors.keyClientToServer);
    expect(bytesToHex(keys.serverToClient)).toBe(vectors.keyServerToClient);
  });

  it("seals records identical to the reference and opens them", async () => {
    const keys = await vectorKeys();
    for (const r of vectors.records) {
      const c2s = r.direction === "client-to-server";
      const key = c2s ? keys.clientToServer : keys.serverToClient;
      const dir = c2s ? DIR_CLIENT_TO_SERVER : DIR_SERVER_TO_CLIENT;
      const sealed = await sealRecord(key, dir, BigInt(r.counter), r.plaintext);
      expect(bytesToHex(sealed)).toBe(r.record);
      expect(await openRecord(key, dir, BigInt(r.counter), hexToBytes(r.record))).toBe(r.plaintext);
    }
  });

  it("rejects tampering, wrong counter, wrong direction and truncation", async () => {
    const keys = await vectorKeys();
    const record = hexToBytes(vectors.records[1].record); // server-to-client, counter 0
    const flipped = record.slice();
    flipped[flipped.length - 1] ^= 1;
    expect(await openRecord(keys.serverToClient, DIR_SERVER_TO_CLIENT, 0n, flipped)).toBeNull();
    expect(await openRecord(keys.serverToClient, DIR_SERVER_TO_CLIENT, 1n, record)).toBeNull();
    expect(await openRecord(keys.serverToClient, DIR_CLIENT_TO_SERVER, 0n, record)).toBeNull();
    expect(await openRecord(keys.clientToServer, DIR_SERVER_TO_CLIENT, 0n, record)).toBeNull();
    expect(await openRecord(keys.serverToClient, DIR_SERVER_TO_CLIENT, 0n, record.slice(0, 10))).toBeNull();
  });

  it("derives different keys for a different token", async () => {
    const hello = await importVectorPrivateKey();
    const other = await deriveKeys(
      hello,
      hexToBytes(vectors.clientPublicKey),
      hexToBytes(vectors.clientNonce),
      hexToBytes(vectors.serverPublicKey),
      hexToBytes(vectors.serverNonce),
      "another-token",
    );
    expect(bytesToHex(other.clientToServer)).not.toBe(vectors.keyClientToServer);
  });

  it("rejects an off-curve server public key", async () => {
    const bad = hexToBytes(vectors.serverPublicKey);
    bad[64] ^= 1;
    await expect(
      deriveKeys(
        await importVectorPrivateKey(),
        hexToBytes(vectors.clientPublicKey),
        hexToBytes(vectors.clientNonce),
        bad,
        hexToBytes(vectors.serverNonce),
        vectors.token,
      ),
    ).rejects.toThrow();
  });
});

describe("hello messages", () => {
  it("builds a hello with a 65-byte point and 16-byte nonce", async () => {
    const hello = await createClientHello();
    const msg = JSON.parse(helloMessage(hello));
    expect(msg.v).toBe(2);
    expect(b64ToBytes(msg.hello.pub)).toHaveLength(65);
    expect(b64ToBytes(msg.hello.nonce)).toHaveLength(16);
  });

  it("parses a valid server hello and rejects malformed ones", () => {
    const good = JSON.stringify({
      v: 2,
      hello: { pub: bytesToB64(new Uint8Array(65)), nonce: bytesToB64(new Uint8Array(16)) },
    });
    expect(parseServerHello(good)).not.toBeNull();
    expect(parseServerHello("not json")).toBeNull();
    expect(parseServerHello('{"v":3,"hello":{}}')).toBeNull();
    expect(
      parseServerHello(
        JSON.stringify({ v: 2, hello: { pub: bytesToB64(new Uint8Array(64)), nonce: bytesToB64(new Uint8Array(16)) } }),
      ),
    ).toBeNull();
  });
});

describe("SecureChannel", () => {
  it("round-trips in order and refuses out-of-order or replayed records", async () => {
    const keys = await vectorKeys();
    const server = (counter: bigint, text: string) =>
      sealRecord(keys.serverToClient, DIR_SERVER_TO_CLIENT, counter, text);
    const channel = new SecureChannel(keys.clientToServer, keys.serverToClient);

    expect(await channel.open(await server(0n, "a"))).toBe("a");
    expect(await channel.open(await server(0n, "a"))).toBeNull(); // replay
    expect(await channel.open(await server(2n, "c"))).toBeNull(); // skipped one
    expect(await channel.open(await server(1n, "b"))).toBe("b");

    const first = await channel.seal("x");
    const second = await channel.seal("y");
    expect(await openRecord(keys.clientToServer, DIR_CLIENT_TO_SERVER, 0n, first)).toBe("x");
    expect(await openRecord(keys.clientToServer, DIR_CLIENT_TO_SERVER, 1n, second)).toBe("y");
  });
});
